                            // (docs/adr/0140), and its definition where this module
                            // writes it for the form held in place.
                            let scan = rust_view::scan_walk(&walked, site);
                            if let Some(item) = scan.item {
                                obj.insert("view_held_walk_item".into(), item.into());
                            }
