/// `struct { T slots[N]; uint32_t generation[N]; uint32_t bitmap[(N+31)/32];
/// uint32_t count; }` shape per spec lines 2573-2575 verbatim, with the
/// `<snake>_insert/_remove/_find_by_index` API per spec line 2575 and
/// `_get/_foreach/_len/_capacity` per spec lines 2613-2618. Handle is a
/// POD `typedef struct { uint32_t raw; } <snake>_handle_t;` packing slot
/// (low 16) + generation (high 16) — ABI-identical to the Cpp POD, Rust
/// tuple newtype, Kotlin @JvmInline value class, and Go uint32 newtype
/// emits. Iteration via `<snake>_foreach(self, fn, user)` callback
/// (locked 2026-05-13).
fn render_bounded_collection_c(
    env: &minijinja::Environment<'_>,
    m: &crate::forge::model::BoundedCollectionModel,
    _imports: &[ImportContext],
    options: &crate::ForgeCompileOptions,
) -> Result<String, ForgeError> {
    let inputs = resolve_bounded_collection_inputs(m, options, crate::generator::Language::C11)?;
    let tmpl = env
        .get_template("bounded_collection.h.jinja2")
        .map_err(|e| {
            ForgeError::from(GenerateError::TemplateLoad(format!(
                "bounded_collection.h.jinja2 (c11): {e}"
            )))
        })?;

    let pascal = filters::to_pascal_case(m.name.clone());
    let snake = filters::to_snake_case(m.name.clone());
    let element_pascal = filters::to_pascal_case(m.element_type.clone());
    let element_snake = filters::to_snake_case(m.element_type.clone());
    let upper_name = to_upper_snake(&m.name);
    let guard = format!("SCE_FORGE_{}_H", upper_name);
    // The C11 codec / procedure emit names struct fields via
    // `codec_field_id` (snake_case for C11). Mirror that here so
    // `slots[slot].<field>` matches the element-type's emitted
    // member name.
    let index_by_field_snake = m
        .index_by
        .as_ref()
        .map(|f| filters::to_snake_case(f.clone()))
        .unwrap_or_default();

    let ctx = minijinja::context! {
        name => &m.name,
        pascal => pascal,
        snake => snake,
        upper_name => upper_name,
        guard => guard,
        element_pascal => element_pascal,
        element_snake => element_snake,
        capacity => inputs.capacity,
        on_overflow => inputs.on_overflow_str,
        overflow_is_oldest_wins => inputs.overflow_is_oldest_wins,
        ordering => inputs.ordering_str,
        concurrency => inputs.concurrency_str,
        has_index_by => m.index_by.is_some(),
        index_by_field => index_by_field_snake,
        index_by_c_type => inputs.index_type,
        index_imports => inputs.index_imports,
        runtime_dep => "self-contained — <stdint.h> + <stdbool.h> + <stddef.h> only",
    };
    tmpl.render(ctx).map_err(|e| {
        ForgeError::from(GenerateError::TemplateRender(format!(
            "bounded_collection.h.jinja2 (c11): {e}"
        )))
    })
}

/// Render a `<sce:kind="bounded-collection">` document for the Go
/// backend (SCE Protocol-Synthesis RFC §synth-5-L, item C6). Emits `[N]T` + `[N]bool`
/// occupancy + `[N]uint32` generation + `int count` per spec line 2579
/// verbatim. Handle is `type <Pascal>Handle uint32` with receiver methods
/// `Slot()` / `Generation()` (ABI-parity with the Rust / Cpp /
/// Kotlin / C11 uint32-wide Handle).
/// Iteration via `ForEach(fn func(T))` callback. Overflow under
/// reject/diagnostic-event returns the sentinel
/// `Err<Pascal>Overflow`; under oldest-wins eviction always succeeds.
///
/// Element-type cross-package import requires `go_module_prefix` to be
/// set so the qualified `<element_snake>.<ElementPascal>` reference
/// resolves at compile time (mirrors `<sce:import>` for codec). Missing
/// prefix surfaces as `InvalidConfig` with the same message shape as
/// `validate_options`.
fn render_bounded_collection_go(
    env: &minijinja::Environment<'_>,
    m: &crate::forge::model::BoundedCollectionModel,
    _imports: &[ImportContext],
    options: &crate::ForgeCompileOptions,
) -> Result<String, ForgeError> {
    let inputs = resolve_bounded_collection_inputs(m, options, crate::generator::Language::Go)?;
    let tmpl = env
        .get_template("bounded_collection.go.jinja2")
        .map_err(|e| {
            ForgeError::from(GenerateError::TemplateLoad(format!(
                "bounded_collection.go.jinja2 (go): {e}"
            )))
        })?;

    let pascal = filters::to_pascal_case(m.name.clone());
    let snake = filters::to_snake_case(m.name.clone());
    let package = filters::to_snake_case(m.name.clone());
    let element_pascal = filters::to_pascal_case(m.element_type.clone());
    let element_snake = filters::to_snake_case(m.element_type.clone());

    // Cross-package element-type access requires `go_module_prefix`
    // (Go has no relative-package imports). Missing prefix surfaces
    // the same InvalidConfig shape as `validate_options` for the
    // `<sce:import>` path so error messages are consistent.
    let element_import_stmt = go_element_import_statement(
        "bounded-collection",
        &m.name,
        &m.element_type,
        &element_snake,
        options,
    )?;

    // Element-type is qualified via the package name (snake_case): the element
    // is a codec, a STATEFUL import, which keeps the package's own name
    // (`forge_import_identity`).
    let element_qualified = format!("{element_snake}.{element_pascal}");

    // Go codec emits struct fields in PascalCase (`codec_field_id`
    // arm). Mirror that here so `slots[slot].<Field>` matches the
    // element-type's emitted member name.
    let index_by_field_pascal = m
        .index_by
        .as_ref()
        .map(|f| filters::to_pascal_case(f.clone()))
        .unwrap_or_default();

    let ctx = minijinja::context! {
        name => &m.name,
        pascal => pascal,
        snake => snake,
        package => package,
        element_pascal => element_pascal,
        element_snake => element_snake,
        element_qualified => element_qualified,
        has_element_import => true,
        element_import_stmt => element_import_stmt,
        capacity => inputs.capacity,
        on_overflow => inputs.on_overflow_str,
        overflow_is_oldest_wins => inputs.overflow_is_oldest_wins,
        ordering => inputs.ordering_str,
        concurrency => inputs.concurrency_str,
        has_index_by => m.index_by.is_some(),
        index_by_field_pascal => index_by_field_pascal,
        // An element the Go backend prints from its plan presents the index
        // field through its method (docs/adr/0081 step 4).
        index_by_accessor => options
            .bounded_collection_resolutions
            .as_ref()
            .and_then(|map| map.get(&m.name))
            .is_some_and(|resolution| resolution.element_go_printed),
        index_by_go_type => inputs.index_type,
        index_imports => inputs.index_imports,
        runtime_dep => "self-contained — Go stdlib `errors` only",
    };
    tmpl.render(ctx).map_err(|e| {
        ForgeError::from(GenerateError::TemplateRender(format!(
            "bounded_collection.go.jinja2 (go): {e}"
        )))
    })
}

/// Render a `<sce:kind="bounded-collection">` document for the Python
/// backend (SCE Protocol-Synthesis RFC §synth-5-L, item C6). Emits `list` of length N
/// initialized to `None` + `bytearray(N)` occupancy + per-slot
/// generation packed into a sibling `bytearray(N * 2)` (u16 per slot,
/// little-endian internal) + `int count` per spec lines 2580-2581. The
/// internal generation representation is implementation-private; the
/// wire-format Handle remains the packed u32 (slot|gen) shape so
/// cross-backend interop holds.
///
/// Handle is `@dataclasses.dataclass(frozen=True, slots=True)` over
/// `raw: int` with slot/generation property accessors (immutable +
/// hashable + zero __dict__).
/// Overflow under reject/diagnostic-event returns `None` via
/// `Optional[Handle]` (Pythonic
/// `dict.get()` precedent for "expected absence"). Iteration via
/// `__iter__` generator + an explicit `for_each(fn)` named method for
/// callers that prefer the named form (parity with the foreach API
/// shape on Cpp/Kotlin/Go/C11).
fn render_bounded_collection_python(
    env: &minijinja::Environment<'_>,
    m: &crate::forge::model::BoundedCollectionModel,
    _imports: &[ImportContext],
    options: &crate::ForgeCompileOptions,
) -> Result<String, ForgeError> {
    let inputs = resolve_bounded_collection_inputs(m, options, crate::generator::Language::Python)?;
    let tmpl = env
        .get_template("bounded_collection.py.jinja2")
        .map_err(|e| {
            ForgeError::from(GenerateError::TemplateLoad(format!(
                "bounded_collection.py.jinja2 (python): {e}"
            )))
        })?;

    let pascal = filters::to_pascal_case(m.name.clone());
    let snake = filters::to_snake_case(m.name.clone());
    let element_pascal = filters::to_pascal_case(m.element_type.clone());
    let element_snake = filters::to_snake_case(m.element_type.clone());

    // Python uses relative-package imports (`from .<snake> import
    // <Pascal>`) — the existing codec / procedure import resolver
    // emits this exact shape (resolve_single_import Python arm).
    // Mirror it for the BC's implicit element-type reference.
    let element_import_stmt = format!("from .{element_snake} import {element_pascal}");

    // Python codec emits struct fields in snake_case (`codec_field_id`
    // Python arm). Mirror that here so `_slots[slot].<field>` matches
    // the element-type's emitted member name.
    let index_by_field_snake = m
        .index_by
        .as_ref()
        .map(|f| filters::to_snake_case(f.clone()))
        .unwrap_or_default();

    let ctx = minijinja::context! {
        name => &m.name,
        pascal => pascal,
        snake => snake,
        element_pascal => element_pascal,
        element_snake => element_snake,
        has_element_import => true,
        element_import_stmt => element_import_stmt,
        capacity => inputs.capacity,
        on_overflow => inputs.on_overflow_str,
        overflow_is_oldest_wins => inputs.overflow_is_oldest_wins,
        ordering => inputs.ordering_str,
        concurrency => inputs.concurrency_str,
        has_index_by => m.index_by.is_some(),
        index_by_field_snake => index_by_field_snake,
        index_by_py_type => inputs.index_type,
        index_imports => inputs.index_imports,
        runtime_dep => "self-contained — Python stdlib `dataclasses` + `typing` only",
    };
    tmpl.render(ctx).map_err(|e| {
        ForgeError::from(GenerateError::TemplateRender(format!(
            "bounded_collection.py.jinja2 (python): {e}"
        )))
    })
}

/// Render a `<sce:kind="link">` document for the C11 backend
/// (SCE Protocol-Synthesis RFC §synth-5-C, item B6). Mirrors `render_link_rust` but
/// emits a header that composes a `sce_forge_link_t` driver handle
/// from `backends/c/forge-runtime/include/sce/forge/link.h`. The dispatch
/// shape is the canonical Linux-kernel separate-vtable
/// pattern (`const sce_forge_link_ops_t *ops` + `void *self`) so the
/// ops table can live in flash/ROM on MCU targets.
///
/// Returns the link's header and, for a link that sends through a transmit
/// pool, the header of its sends into a pool of the pool's lending type,
/// `<link>_over.h` (docs/adr/0111 D4), which includes `<pool>_over.h`: the
/// link's own header includes the pool's header alone.
fn render_link_c(
    env: &minijinja::Environment<'_>,
    m: &LinkModel,
    imports: &[ImportContext],
    options: &crate::ForgeCompileOptions,
) -> Result<(String, Option<GeneratedFile>), ForgeError> {
    let tmpl = env.get_template("link.h.jinja2").map_err(|e| {
        ForgeError::from(GenerateError::TemplateLoad(format!(
            "link.h.jinja2 (c11): {e}"
        )))
    })?;
    let events = link_events::resolve(m, imports, crate::generator::Language::C11, options)?;
    let sends_through_a_pool = events
        .as_ref()
        .is_some_and(link_events::LinkEvents::sends_through_a_pool);
    let snake_name = filters::to_snake_case(m.name.clone());
    let upper_name = to_upper_snake(&m.name);
    let guard = format!("SCE_FORGE_{}_H", upper_name);
    let over_guard = format!("SCE_FORGE_{}_OVER_H", upper_name);
    // Item C10 listener-pair: orchestrator-resolved flag. Same shape as
    // the Rust backend; `None` collapses to `false`.
    let is_listener_with_sibling = options
        .listener_links
        .as_ref()
        .is_some_and(|s| s.contains(&m.name));
    let ctx = minijinja::context! {
        name => &m.name,
        snake_name => snake_name.clone(),
        upper_name => upper_name,
        guard => guard,
        over_guard => over_guard,
        class => m.class.to_string(),
        framer => &m.framer,
        framer_snake => filters::to_snake_case(m.framer.clone()),
        backpressure => m.backpressure.to_string(),
        inbound => m.inbound.iter().map(|e| minijinja::context! {
            event => &e.event,
            when => e.when.clone().unwrap_or_default(),
            has_when => e.when.is_some(),
        }).collect::<Vec<_>>(),
        outbound => m.outbound.iter().map(|e| minijinja::context! {
            event => &e.event,
            encode => &e.encode,
        }).collect::<Vec<_>>(),
        stage_pool => m.stage_pool.clone().unwrap_or_default(),
        has_stage_pool => m.stage_pool.is_some(),
        is_listener_with_sibling => is_listener_with_sibling,
        events => events,
    };
    let rendered = tmpl.render(&ctx).map_err(|e| {
        ForgeError::from(GenerateError::TemplateRender(format!(
            "link.h.jinja2 (c11): {e}"
        )))
    })?;
    if is_listener_with_sibling {
        check_listener_sibling_emitted_c(&m.name, &snake_name, &rendered)?;
    }
    if !sends_through_a_pool {
        return Ok((rendered, None));
    }
    let over_tmpl = env.get_template("link_over.h.jinja2").map_err(|e| {
        ForgeError::from(GenerateError::TemplateLoad(format!(
            "link_over.h.jinja2 (c11): {e}"
        )))
    })?;
    let over = over_tmpl.render(ctx).map_err(|e| {
        ForgeError::from(GenerateError::TemplateRender(format!(
            "link_over.h.jinja2 (c11): {e}"
        )))
    })?;
    Ok((rendered, Some((format!("{snake_name}_over.h"), over))))
}

/// Item C10 codegen self-check for the §synth-5-C listener-pair Sibling
/// emission invariant on the C11 backend (RFC §synth-5-C lines 849-856).
/// The C11 template emits `} {snake_name}_established_session_t;`
/// inside the `{% if is_listener_with_sibling %}` block. If the
/// rendered output is missing that exact typedef suffix, fire
/// `link/listener-link-not-paired-with-established-sibling`.
///
/// Mirrors [`check_reassembly_peer_id_zid_invariant_c11`] (item C9
/// precedent at generator.rs:10262-10284).
fn check_listener_sibling_emitted_c(
    link_name: &str,
    snake_name: &str,
    rendered: &str,
) -> Result<(), ForgeError> {
    let _ = snake_name; // marker presence is the contract; symbol name is no longer the validator key
    if crate::forge::codegen_markers::contains_emit_marker(
        rendered,
        "link.listener.established-session",
    ) {
        Ok(())
    } else {
        Err(ForgeError::Validation(Box::new(
            crate::forge::error::ValidationError::LinkListenerLinkNotPairedWithEstablishedSibling {
                link_name: link_name.to_string(),
                language: "c11".to_string(),
            },
        )))
    }
}

/// Render the `.h` header for a `<sce:kind="worker">` document on the
/// C11 backend (SCE Protocol-Synthesis RFC §synth-5-D, item C2). The worker's
/// inbox is the queue it imports (`<sce:inbox ref>`): the header includes that
/// queue's generated header and names its type as the worker's inbox, and states
/// the driving link and the outbox. The ring, its storage and its ordering are
/// the queue document's, generated once in the queue's own header, so a worker
/// has no translation unit of its own.
fn render_worker_c_header(
    env: &minijinja::Environment<'_>,
    m: &WorkerModel,
    imports: &[ImportContext],
) -> Result<String, ForgeError> {
    let tmpl = env.get_template("worker.h.jinja2").map_err(|e| {
        ForgeError::from(GenerateError::TemplateLoad(format!(
            "worker.h.jinja2 (c11): {e}"
        )))
    })?;
    let queue = worker_inbox_queue(m, imports)?;
    let snake_name = filters::to_snake_case(m.name.clone());
    let upper_name = to_upper_snake(&m.name);
    let guard = format!("SCE_FORGE_{}_H", upper_name);
    let ctx = minijinja::context! {
        name => &m.name,
        snake_name => snake_name,
        upper_name => upper_name,
        guard => guard,
        inbox_alias => &m.inbox.queue_ref,
        queue_name => &queue.document_name,
        queue_snake => filters::to_snake_case(queue.document_name.clone()),
        link_rx => &m.link_rx,
        outbox => m.outbox.clone().unwrap_or_default(),
        has_outbox => m.outbox.is_some(),
    };
    tmpl.render(ctx).map_err(|e| {
        ForgeError::from(GenerateError::TemplateRender(format!(
            "worker.h.jinja2 (c11): {e}"
        )))
    })
}

/// A file a render writes beside the document's own: its name and its text.
type GeneratedFile = (String, String);

/// Render a `<sce:kind="buffer-pool">` document for the C11 backend
/// (SCE Protocol-Synthesis RFC §synth-5-E, items B7 + C5). Mirrors `render_buffer_pool_rust`
/// but emits a header that places the slot storage table in the
/// section declared by `<sce:section>` via `__attribute__((section,
/// aligned))`. The sidecar linker fragment that pairs with this
/// header is rendered separately via [`render_buffer_pool_linker_fragment`]
/// and pushed onto `GeneratedOutput.files` by the dispatcher.
/// C5 wires §synth-5-I cache-maintenance intrinsic calls into the FSM
/// edges per spec lines 1182-1197 with the same gating semantics as
/// the Rust template.
///
/// Returns the pool's header and, beside it, the header of its lending form,
/// `<pool>_over.h` (docs/adr/0111 D4): `<pool>_over_t` over storage the
/// caller holds, rendered from the same context so the two cannot disagree
/// about the pool. Only a program that lends includes it; a `shared` pool's
/// header includes it too, since its own storage is kept in that type.
fn render_buffer_pool_c(
    env: &minijinja::Environment<'_>,
    m: &BufferPoolModel,
    _imports: &[ImportContext],
    options: &crate::ForgeCompileOptions,
) -> Result<(String, GeneratedFile), ForgeError> {
    let tmpl = env.get_template("buffer_pool.h.jinja2").map_err(|e| {
        ForgeError::from(GenerateError::TemplateLoad(format!(
            "buffer_pool.h.jinja2 (c11): {e}"
        )))
    })?;
    let snake_name = filters::to_snake_case(m.name.clone());
    let upper_name = to_upper_snake(&m.name);
    let guard = format!("SCE_FORGE_{}_H", upper_name);
    let over_guard = format!("SCE_FORGE_{}_OVER_H", upper_name);
    // C5: deploy-aware cache-maintenance gating; mirror the Rust
    // template's `has_speculative_prefetch` derivation.
    let has_speculative_prefetch = options
        .cache_platform
        .as_ref()
        .is_some_and(|p| p.has_speculative_prefetch);
    // Reassembly variant context — mirror of Rust render fn so
    // both backends emit the same per-slot bitmap + deadline + ZID
    // shape from the same input model (RFC §synth-5-M lines 2680-2698 +
    // 2976-2981).
    let (variant_reassembly, max_fragments_per_message, reassembly_timeout_ms, per_peer_quota) =
        match &m.variant {
            crate::forge::model::BufferPoolVariant::Default => (false, 0u32, 0u32, 0u32),
            crate::forge::model::BufferPoolVariant::Reassembly(cfg) => (
                true,
                cfg.max_fragments_per_message,
                cfg.reassembly_timeout_ms,
                cfg.per_peer_quota,
            ),
        };
    // Analyzer-layer annotations (RFC §synth-5-E lines 1349-1365),
    // rendered from the same `ownership_contract` table that pins
    // `<sce/sample.h>`. Keyed by contract suffix so the template names
    // the declaration it annotates rather than indexing positionally;
    // `check_analyzer_annotations_emitted_c11` below fails the render if
    // the template drops one, so a missing key cannot degrade to
    // silently-inert analyzer coverage.
    //
    // docs/adr/0111 D4: every contract is rendered for the lending pool's
    // function too, `<pool>_over<suffix>` keyed `_over<suffix>`, whose pool is
    // its first argument; one only the lending pool declares is rendered for
    // it alone.
    let mut analyzer: std::collections::BTreeMap<String, String> =
        std::collections::BTreeMap::new();
    for c in crate::forge::ownership_contract::POOL_CONTRACTS.iter() {
        if !c.over_only {
            analyzer.insert(
                c.suffix.to_string(),
                c.rendered_lines(&snake_name).join("\n"),
            );
        }
        analyzer.insert(
            format!("_over{}", c.suffix),
            c.rendered_lines_over(&snake_name).join("\n"),
        );
    }
    // Lifecycle-FSM context shared by both backends: markers, the
    // runtime seam, and the per-edge cache resolution.
    let cache_maintain = m.cache_policy == crate::forge::model::CachePolicy::Maintain;
    let fsm_ctx = buffer_pool_fsm_context(cache_maintain, has_speculative_prefetch);
    let ctx = minijinja::context! {
        name => &m.name,
        snake_name => snake_name.clone(),
        upper_name => upper_name.clone(),
        guard => guard,
        over_guard => over_guard,
        slot_count => m.slot_count,
        slot_size => m.slot_size,
        section => &m.section,
        section_upper => m.section.to_uppercase(),
        alignment => m.alignment,
        dma_channel => m.dma_channel.clone().unwrap_or_default(),
        has_dma_channel => m.dma_channel.is_some(),
        cache_policy => m.cache_policy.to_string(),
        // `<sce:sharing>` (docs/adr/0111 D4), as for the Rust book.
        sharing => m.sharing.as_str(),
        shared => m.sharing == crate::forge::model::PoolSharing::Shared,
        analyzer => analyzer,
        // C5 cache-maintenance gating; mirror of Rust template
        // context shape so per-backend template authors can reach for
        // the same names without per-backend wiring guesswork.
        cache_maintain => cache_maintain,
        // Slot-lifecycle FSM, rendered from `buffer_pool_fsm` rather
        // than restated in the template.
        markers => fsm_ctx.markers,
        seam => fsm_ctx.seam,
        addresses => fsm_ctx.addresses,
        edge_cache => fsm_ctx.author_cache,
        needs_clean_extern => fsm_ctx.needs_clean_extern,
        needs_invalidate_extern => fsm_ctx.needs_invalidate_extern,
        has_speculative_prefetch => has_speculative_prefetch,
        // Reassembly variant (item C9).
        variant_reassembly => variant_reassembly,
        max_fragments_per_message => max_fragments_per_message,
        reassembly_timeout_ms => reassembly_timeout_ms,
        per_peer_quota => per_peer_quota,
    };
    let rendered = tmpl.render(&ctx).map_err(|e| {
        ForgeError::from(GenerateError::TemplateRender(format!(
            "buffer_pool.h.jinja2 (c11): {e}"
        )))
    })?;
    check_analyzer_annotations_emitted_c11(&m.name, &snake_name, &rendered, PoolHeaderC11::Own)?;
    if variant_reassembly {
        check_reassembly_peer_id_zid_invariant_c11(&m.name, &snake_name, &rendered)?;
    }
    let over_tmpl = env.get_template("buffer_pool_over.h.jinja2").map_err(|e| {
        ForgeError::from(GenerateError::TemplateLoad(format!(
            "buffer_pool_over.h.jinja2 (c11): {e}"
        )))
    })?;
    let over = over_tmpl.render(ctx).map_err(|e| {
        ForgeError::from(GenerateError::TemplateRender(format!(
            "buffer_pool_over.h.jinja2 (c11): {e}"
        )))
    })?;
    check_analyzer_annotations_emitted_c11(&m.name, &snake_name, &over, PoolHeaderC11::Over)?;
    Ok((rendered, (format!("{snake_name}_over.h"), over)))
}

/// Which of a C11 buffer pool's two headers a check reads (docs/adr/0111 D4).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PoolHeaderC11 {
    /// `<pool>.h`: the pool over the header's own storage, whose functions are
    /// `<pool><suffix>`.
    Own,
    /// `<pool>_over.h`: the lending type, `<pool>_over_t`, whose functions are
    /// `<pool>_over<suffix>`.
    Over,
}

impl PoolHeaderC11 {
    /// The template the header is rendered from.
    fn template(self) -> &'static str {
        match self {
            Self::Own => "buffer_pool.h.jinja2",
            Self::Over => "buffer_pool_over.h.jinja2",
        }
    }
}

/// Codegen self-check for the analyzer-layer annotations
/// (RFC §synth-5-E lines 1349-1365).
///
/// The template reaches into the `analyzer` map by suffix. minijinja
/// resolves an unknown key to undefined and renders it as the empty
/// string, so a typo or a dropped lookup would strip analyzer coverage
/// from every generated pool while every existing test stayed green —
/// the silently-inert hook class §2.4 invariant 1 forbids. Fail the
/// render instead: the contract table is the authority on what must
/// appear, so it is also what this checks against.
fn check_analyzer_annotations_emitted_c11(
    pool_name: &str,
    snake_name: &str,
    rendered: &str,
    header: PoolHeaderC11,
) -> Result<(), ForgeError> {
    // docs/adr/0111 D4: the lending pool, `<pool>_over_t`, declares every
    // function in `<pool>_over.h`, and the pool over the header's own storage
    // every one but those a lent slot crosses an interface by in `<pool>.h`.
    for contract in crate::forge::ownership_contract::POOL_CONTRACTS.iter() {
        let (name, key, lines) = match header {
            PoolHeaderC11::Own if contract.over_only => continue,
            PoolHeaderC11::Own => (
                contract.qualified_name(snake_name),
                contract.suffix.to_string(),
                contract.rendered_lines(snake_name),
            ),
            PoolHeaderC11::Over => (
                contract.qualified_name_over(snake_name),
                format!("_over{}", contract.suffix),
                contract.rendered_lines_over(snake_name),
            ),
        };
        for line in lines {
            if !rendered.contains(&line) {
                return Err(ForgeError::from(GenerateError::TemplateRender(format!(
                    "{template} (c11): pool `{pool_name}` rendered without \
                     the analyzer-layer annotation for `{name}`:\n  {line}\n\
                     The template must emit `analyzer[\"{key}\"]` immediately above that \
                     declaration; without it, non-Clang toolchains lose the \
                     ownership contract entirely (RFC §synth-5-E lines 1349-1365).",
                    template = header.template(),
                ))));
            }
        }
    }
    Ok(())
}

/// Item C9 codegen self-check for the §synth-5-M reassembly-variant peer-id
/// invariant on the C11 backend (RFC §synth-5-M lines 2976-2981). The C11
/// template emits `typedef uint8_t <snake>_peer_id_t[16];` on every
/// reassembly-variant pool. If the rendered header is missing that
/// exact byte-array shape, fire
/// `reassembly/peer-id-not-zid-on-established-session`.
fn check_reassembly_peer_id_zid_invariant_c11(
    pool_name: &str,
    snake_name: &str,
    rendered_h: &str,
) -> Result<(), ForgeError> {
    let _ = snake_name;
    if crate::forge::codegen_markers::contains_emit_marker(rendered_h, "reassembly.peer-id-zid") {
        Ok(())
    } else {
        Err(ForgeError::Validation(Box::new(
            crate::forge::error::ValidationError::ReassemblyPeerIdNotZidOnEstablishedSession {
                pool_name: pool_name.to_string(),
                language: "c11".to_string(),
            },
        )))
    }
}

/// Render the sidecar linker fragment that pairs with the buffer-pool
/// .h emitted by [`render_buffer_pool_c`] (RFC §synth-5-E lines 1031-1086).
/// Returns `(filename, content)` so the dispatcher can push the pair
/// onto `GeneratedOutput.files`.
///
/// Carries a codegen self-check that fires `mem/inter-pool-padding-not-emitted`
/// when the rendered fragment is missing the inter-pool `. = ALIGN(..);`
/// sentinel — the artifact §synth-5-E lines 1059-1064 mandates as the
/// audible diff trace for any PR that drops it.
fn render_buffer_pool_linker_fragment(
    env: &minijinja::Environment<'_>,
    m: &BufferPoolModel,
) -> Result<(String, String), ForgeError> {
    let tmpl = env.get_template("buffer_pool.ld.jinja2").map_err(|e| {
        ForgeError::from(GenerateError::TemplateLoad(format!(
            "buffer_pool.ld.jinja2 (c11): {e}"
        )))
    })?;
    let snake_name = filters::to_snake_case(m.name.clone());
    let ctx = minijinja::context! {
        name => &m.name,
        snake_name => snake_name.clone(),
        section => &m.section,
        section_upper => m.section.to_uppercase(),
        alignment => m.alignment,
    };
    let body = tmpl.render(ctx).map_err(|e| {
        ForgeError::from(GenerateError::TemplateRender(format!(
            "buffer_pool.ld.jinja2 (c11): {e}"
        )))
    })?;
    check_inter_pool_padding_invariant(&m.name, &body)?;
    let filename = format!("{}_pool.ld", snake_name);
    Ok((filename, body))
}

/// Codegen self-check for the §synth-5-E inter-pool padding invariant
/// (lines 1059-1064). The buffer-pool linker fragment must carry an
/// explicit `. = ALIGN(<n>);` sentinel inside the output section body
/// so the post-pool boundary stays alignment-pinned even if a downstream
/// master script splices another section in via INCLUDE. If the
/// rendered fragment is missing that artifact, emit
/// `mem/inter-pool-padding-not-emitted` (codegen invariant violation,
/// not an authoring mistake — fires only when the template itself
/// drops the sentinel).
///
/// This check reads the emit marker, so it decides presence only. That
/// the sentinel is placed where it does any work is decided by
/// `buffer_pool_linker_fragment_aligns_the_post_pool_boundary`, which
/// links the fragment: written after the closing brace the directive
/// advances only the location counter, which a region-allocated
/// successor ignores, and this check would still pass.
fn check_inter_pool_padding_invariant(
    pool_name: &str,
    rendered_ld: &str,
) -> Result<(), ForgeError> {
    if crate::forge::codegen_markers::contains_emit_marker(rendered_ld, "mem.inter-pool-padding") {
        Ok(())
    } else {
        Err(ForgeError::Validation(Box::new(
            crate::forge::error::ValidationError::BufferPoolInterPoolPaddingNotEmitted {
                name: pool_name.to_string(),
            },
        )))
    }
}

