    #[test]
    fn type_name_is_the_bare_lookup_for_every_primitive() {
        // Resolution only ever adds the enum arm: for every primitive the
        // context answers exactly what the per-language table does, on
        // all six backends, so moving the import table inside `LangCtx`
        // changed no primitive's spelling.
        let cases = &[
            SceType::Uint8,
            SceType::Int32,
            SceType::Float64,
            SceType::Bool,
            SceType::String,
            SceType::Bytes,
        ];
        for lang in crate::forge::codegen_matrix::emitting(ForgeKind::Transform) {
            let l = LangCtx::new(lang, &[]);
            for ty in cases {
                let bare = match lang {
                    crate::generator::Language::Cpp => cpp_type(ty),
                    crate::generator::Language::C11 => c_type(ty),
                    crate::generator::Language::Kotlin => kotlin_type(ty),
                    crate::generator::Language::Rust => rust_type(ty),
                    crate::generator::Language::Go => go_type(ty),
                    crate::generator::Language::Python => python_type(ty),
                    crate::generator::Language::Swift => {
                        unreachable!("swift emits no transform, so it is not iterated")
                    }
                };
                assert_eq!(l.type_name(ty), bare, "{lang:?}/{ty:?}");
            }
        }
    }

    #[test]
    fn an_enum_alias_resolves_to_its_qualified_type_everywhere_a_type_is_asked() {
        // Each backend returns the qualified type name the import was
        // enriched with — the per-backend separator matrix lives in
        // `validate_and_enrich_imports`'s Enum arm, not here.
        //
        // ⚠ All three questions, not only `type_name`: the defect this
        // context exists to prevent was a render asking for a PARAMETER
        // type through a path that never resolved, while the plain type
        // did. An enum is integer-backed, so it passes by value and its
        // parameter type is its type.
        let cases = &[
            (
                crate::generator::Language::Cpp,
                "SCE::Generated::Result::Result",
            ),
            (crate::generator::Language::C11, "Result_t"),
            (crate::generator::Language::Kotlin, "Result"),
            (crate::generator::Language::Rust, "result::Result"),
            (crate::generator::Language::Go, "result.Result"),
            (crate::generator::Language::Python, "result.Result"),
        ];
        for (lang, qualified) in cases {
            let imports = vec![import_with_enum_qualified("Result", qualified)];
            let l = LangCtx::new(*lang, &imports);
            let ty = enum_ref("Result");
            assert_eq!(l.type_name(&ty), *qualified, "type_name {lang:?}");
            assert_eq!(l.param_type(&ty), *qualified, "param_type {lang:?}");
            assert!(
                l.format_param("r", &ty).contains(qualified),
                "format_param {lang:?}: {}",
                l.format_param("r", &ty)
            );
        }
    }

    #[test]
    #[should_panic(expected = "reached a context built by LangCtx::new that does not carry it")]
    fn an_unimported_alias_panics_naming_the_context() {
        // The parser's `read_type_attr` refuses an unresolved enum alias
        // before codegen runs (`a_type_names_what_the_document_imports`
        // holds that), so this branch is unreachable from a document. The
        // panic surfaces a gate failure at the codegen site rather than
        // emitting wrong code.
        let l = LangCtx::new(crate::generator::Language::Cpp, &[]);
        let _ = l.type_name(&enum_ref("Missing"));
    }

    #[test]
    #[should_panic(expected = "reached a context built by LangCtx::primitive")]
    fn an_enum_reaching_a_primitive_context_names_the_wrong_claim() {
        // `primitive` is a claim that no enum can reach the render. When
        // one does, the message has to point at the constructor that made
        // the claim — that, not the lookup, is where the defect is.
        let l = LangCtx::primitive(crate::generator::Language::Rust);
        let _ = l.type_name(&enum_ref("Result"));
    }

    // ── go_local_spelling ────────────────────────────────────

    #[test]
    fn go_escape_builtins() {
        assert_eq!(go_local_spelling("byte"), "byte_");
        assert_eq!(go_local_spelling("string"), "string_");
        assert_eq!(go_local_spelling("int"), "int_");
        assert_eq!(go_local_spelling("len"), "len_");
        assert_eq!(go_local_spelling("make"), "make_");
        assert_eq!(go_local_spelling("true"), "true_");
        assert_eq!(go_local_spelling("nil"), "nil_");
        assert_eq!(go_local_spelling("iota"), "iota_");
        // The builtins Go added after the first list was written.
        assert_eq!(go_local_spelling("min"), "min_");
        assert_eq!(go_local_spelling("max"), "max_");
        assert_eq!(go_local_spelling("clear"), "clear_");
        assert_eq!(go_local_spelling("any"), "any_");
    }

    /// A local named as the receiver or the engine a generated method binds is
    /// shifted, so a `<foreach item="p">` cannot hide the receiver its body reads
    /// every field through; the shift stays injective (`p_` is `p__`).
    #[test]
    fn go_escape_the_names_a_method_binds() {
        assert_eq!(go_local_spelling("p"), "p_");
        assert_eq!(go_local_spelling("p_"), "p__");
        assert_eq!(go_local_spelling("engine"), "engine_");
        assert_eq!(go_local_spelling("pp"), "pp");
    }

    #[test]
    fn go_escape_non_builtin_unchanged() {
        assert_eq!(go_local_spelling("myVar"), "myVar");
        assert_eq!(go_local_spelling("temperature"), "temperature");
        assert_eq!(go_local_spelling("rpm"), "rpm");
    }

    #[test]
    fn go_escape_a_package_the_body_names_and_the_generators_own_prefix() {
        for name in [
            "math",
            "strconv",
            "lookup",
            "filter",
            "interpolation",
            "optional",
        ] {
            assert_eq!(go_local_spelling(name), format!("{name}_"), "{name}");
        }
        for name in [
            "sceErr",
            "sceFailure",
            "sceValue",
            "sceCond1",
            "scealgorithm",
        ] {
            assert_eq!(go_local_spelling(name), format!("{name}_"), "{name}");
        }
    }

    /// The escape is a shift, so two names the document keeps apart are never
    /// one spelling: `len` is `len_` and an author's own `len_` is `len__`.
    #[test]
    fn go_escape_is_injective() {
        assert_eq!(go_local_spelling("len"), "len_");
        assert_eq!(go_local_spelling("len_"), "len__");
        assert_eq!(go_local_spelling("len__"), "len___");
        let names = [
            "len", "len_", "len__", "x", "x_", "sceErr", "sceErr_", "min", "min_",
        ];
        let spelled: std::collections::BTreeSet<String> =
            names.iter().map(|n| go_local_spelling(n)).collect();
        assert_eq!(spelled.len(), names.len(), "{spelled:?}");
    }

    /// A forge kind's receiver sits in one scope with the author's inputs, so
    /// it must be a name the shift keeps them off: under the generated prefix.
    /// The member accesses of an import are written with the same constant the
    /// templates read, so the two cannot name different receivers.
    #[test]
    fn the_receiver_a_forge_kind_writes_is_one_no_author_name_can_be() {
        assert!(GO_FORGE_RECEIVER.starts_with(GO_GENERATED_PREFIX));
        assert_eq!(
            go_local_spelling(GO_FORGE_RECEIVER),
            format!("{GO_FORGE_RECEIVER}_")
        );
        let mut import = import_with_enum_qualified("smoother", "");
        import.kind = "filter".to_string();
        import.is_stateful = true;
        import.member_name = "Smoother".to_string();
        let renames = stateful_import_method_renames(
            std::slice::from_ref(&import),
            &generator::Language::Go,
            Some(GO_FORGE_RECEIVER),
        );
        assert_eq!(
            renames,
            vec![(
                "smoother.update".to_string(),
                format!("{GO_FORGE_RECEIVER}.Smoother.Update")
            )]
        );
        let procedure = stateful_import_method_renames(
            std::slice::from_ref(&import),
            &generator::Language::Go,
            None,
        );
        assert_eq!(procedure[0].1, "p.Smoother.Update");
    }

