    // ── resolve_single_import ────────────────────────────────

    fn test_import() -> ForgeImport {
        ForgeImport {
            src: "temperature_transform.scxml".to_string(),
            kind: ForgeKind::Transform,
            alias: "temp".to_string(),
            line: None,
            embed_dispatch: None,
            flag_binds: Vec::new(),
            presence: None,
            requires: None,
        }
    }

    fn stateful_import() -> ForgeImport {
        ForgeImport {
            src: "simple_codec.scxml".to_string(),
            kind: ForgeKind::Codec,
            alias: "frame".to_string(),
            line: None,
            embed_dispatch: None,
            flag_binds: Vec::new(),
            presence: None,
            requires: None,
        }
    }

    #[test]
    fn resolve_import_cpp_stateless() {
        let imp = test_import();
        let opts = crate::ForgeCompileOptions::default();
        let ctx = resolve_single_import(&imp, &crate::generator::Language::Cpp, &opts);
        assert_eq!(ctx.alias, "temp");
        assert_eq!(ctx.include_stmt, "#include \"temperature_transform.h\"");
        assert!(!ctx.is_stateful);
        assert_eq!(ctx.namespace, "SCE::Generated::TemperatureTransform");
    }

    #[test]
    fn resolve_import_cpp_stateful() {
        let imp = stateful_import();
        let opts = crate::ForgeCompileOptions::default();
        let ctx = resolve_single_import(&imp, &crate::generator::Language::Cpp, &opts);
        assert!(ctx.is_stateful);
        assert_eq!(ctx.member_name, "frame_");
        assert_eq!(
            ctx.member_type,
            "::SCE::Generated::SimpleCodec::SimpleCodec"
        );
    }

    #[test]
    fn resolve_import_kotlin() {
        let imp = test_import();
        let opts = crate::ForgeCompileOptions::default();
        let ctx = resolve_single_import(&imp, &crate::generator::Language::Kotlin, &opts);
        assert_eq!(
            ctx.include_stmt,
            "import com.sce.generated.temperature_transform.*"
        );
        assert_eq!(ctx.type_name, "TemperatureTransform");
    }

    #[test]
    fn resolve_import_rust_stateless() {
        let imp = test_import();
        let opts = crate::ForgeCompileOptions::default();
        let ctx = resolve_single_import(&imp, &crate::generator::Language::Rust, &opts);
        // Stateless: import module path, not type
        assert_eq!(ctx.include_stmt, "use super::temperature_transform;");
        assert!(!ctx.is_stateful);
    }

    #[test]
    fn resolve_import_rust_stateful() {
        let imp = stateful_import();
        let opts = crate::ForgeCompileOptions::default();
        let ctx = resolve_single_import(&imp, &crate::generator::Language::Rust, &opts);
        // Stateful: import the type directly
        assert_eq!(ctx.include_stmt, "use super::simple_codec::SimpleCodec;");
        assert!(ctx.is_stateful);
    }

    #[test]
    fn resolve_import_go() {
        let imp = test_import();
        let opts = crate::ForgeCompileOptions {
            go_module_prefix: Some("github.com/acme/gen".to_string()),
            ..Default::default()
        };
        let ctx = resolve_single_import(&imp, &crate::generator::Language::Go, &opts);
        // A stateless import is reached through its package qualifier in a
        // function body, so it is imported under the generator's own prefix and
        // no name an author gave a local can hide it.
        assert_eq!(
            ctx.include_stmt,
            "\tsce_temperature_transform \"github.com/acme/gen/temperature_transform\""
        );
        assert_eq!(ctx.namespace, "sce_temperature_transform");
    }

    /// A stateful import is a member used by its type, and a codec reaches its
    /// sibling through the package's own name: it is not aliased.
    #[test]
    fn resolve_import_go_stateful() {
        let imp = stateful_import();
        let opts = crate::ForgeCompileOptions {
            go_module_prefix: Some("github.com/acme/gen".to_string()),
            ..Default::default()
        };
        let ctx = resolve_single_import(&imp, &crate::generator::Language::Go, &opts);
        assert_eq!(ctx.include_stmt, "\t\"github.com/acme/gen/simple_codec\"");
        assert_eq!(ctx.namespace, "simple_codec");
    }

    #[test]
    fn resolve_import_python_stateless() {
        let imp = test_import();
        let opts = crate::ForgeCompileOptions::default();
        let ctx = resolve_single_import(&imp, &crate::generator::Language::Python, &opts);
        // Called through its module in a function body, so imported under the
        // generator's prefix: no author's local can replace the module.
        assert_eq!(
            ctx.include_stmt,
            "from . import temperature_transform as sce_temperature_transform"
        );
        assert_eq!(ctx.namespace, "sce_temperature_transform");
    }

    /// An author's name under the generator's prefix is shifted off the aliases
    /// a stateless import is brought in under, injectively.
    #[test]
    fn python_names_under_the_generators_prefix_are_shifted() {
        assert_eq!(python_local_spelling("sce_x"), "sce_x_");
        assert_eq!(python_local_spelling("sce_x_"), "sce_x__");
        assert_eq!(python_local_spelling("sceX"), "sce_x_");
        assert_eq!(python_local_spelling("scene"), "scene");
        assert_eq!(
            python_module_alias("condition_threshold"),
            "sce_condition_threshold"
        );
        // The alias is itself a name the shift keeps an author off.
        assert_ne!(
            python_local_spelling(&python_module_alias("condition_threshold")),
            python_module_alias("condition_threshold")
        );
    }

    /// What the C generator keeps — the library's names, its own `sce_` prefix
    /// and the underscore-led state it hands a validator — is shifted off an
    /// author's local, injectively, and nothing else is.
    #[test]
    fn c11_names_the_generator_keeps_are_shifted_off_an_authors() {
        assert_eq!(c11_local_spelling("size_t"), "size_t_");
        assert_eq!(c11_local_spelling("size_t_"), "size_t__");
        assert_eq!(c11_local_spelling("sceFoo"), "sce_foo_");
        assert_eq!(c11_local_spelling("sce_failure_"), "sce_failure__");
        assert_eq!(c11_local_spelling("_st"), "_st_");
        assert_eq!(c11_local_spelling("rpm"), "rpm");
        assert_eq!(c11_local_spelling("engineRpm"), "engine_rpm");
        assert_eq!(c11_local_spelling("scene"), "scene");
        // Injective: no two names the document keeps apart meet.
        let names = ["size_t", "size_t_", "size_t__", "_st", "_st_", "x", "x_"];
        let spelled: std::collections::BTreeSet<String> =
            names.iter().map(|n| c11_local_spelling(n)).collect();
        assert_eq!(spelled.len(), names.len(), "{spelled:?}");
    }

    /// What the C++ generator keeps — the fixed-width types, its own `ForgeDomain`,
    /// the `sce_` / `SCE_` prefixes and the trailing underscore of a generated
    /// class member — is shifted off an author's local, injectively, and nothing
    /// else is.
    #[test]
    fn cpp_names_the_generator_keeps_are_shifted_off_an_authors() {
        assert_eq!(cpp_local_spelling("size_t"), "size_t_");
        assert_eq!(cpp_local_spelling("size_t_"), "size_t__");
        assert_eq!(cpp_local_spelling("uint8_t"), "uint8_t_");
        assert_eq!(cpp_local_spelling("ForgeDomain"), "ForgeDomain_");
        assert_eq!(cpp_local_spelling("sce_failure"), "sce_failure_");
        assert_eq!(cpp_local_spelling("SCE_FORGE_X_H"), "SCE_FORGE_X_H_");
        assert_eq!(cpp_local_spelling("alarm_"), "alarm__");
        assert_eq!(cpp_local_spelling("rpm"), "rpm");
        assert_eq!(cpp_local_spelling("engineRpm"), "engineRpm");
        assert_eq!(cpp_local_spelling("scene"), "scene");
        assert_eq!(cpp_local_spelling("delta"), "delta");
        // Injective: no two names the document keeps apart meet.
        let names = [
            "size_t", "size_t_", "size_t__", "alarm_", "alarm__", "x", "x_", "sce_a", "sce_a_",
        ];
        let spelled: std::collections::BTreeSet<String> =
            names.iter().map(|n| cpp_local_spelling(n)).collect();
        assert_eq!(spelled.len(), names.len(), "{spelled:?}");
    }

    /// What the Rust generator keeps — the snake_case its compiler holds a
    /// binding to, and its own `sce_` prefix — is how an author's local is
    /// spelled and shifted off, injectively, and nothing else is.
    #[test]
    fn rust_names_the_generator_keeps_are_shifted_off_an_authors() {
        assert_eq!(rust_local_spelling("engineRpm"), "engine_rpm");
        assert_eq!(rust_local_spelling("rawValue"), "raw_value");
        assert_eq!(rust_local_spelling("rpm"), "rpm");
        assert_eq!(rust_local_spelling("lookup"), "lookup");
        assert_eq!(rust_local_spelling("events"), "events");
        assert_eq!(rust_local_spelling("sce_events"), "sce_events_");
        assert_eq!(rust_local_spelling("sceEvents"), "sce_events_");
        assert_eq!(rust_local_spelling("sce_events_"), "sce_events__");
        assert_eq!(rust_local_spelling("scene"), "scene");
        // Injective on what is already spelled: no two names meet.
        let names = ["sce_a", "sce_a_", "sce_a__", "a", "a_"];
        let spelled: std::collections::BTreeSet<String> =
            names.iter().map(|n| rust_local_spelling(n)).collect();
        assert_eq!(spelled.len(), names.len(), "{spelled:?}");
    }

    /// What the Kotlin generator reaches through — a capitalised name (a class
    /// in qualifier position), the package roots a call is written through and
    /// its own `sce` prefix — is shifted off an author's local, injectively, and
    /// nothing else is.
    #[test]
    fn kotlin_names_the_generator_reaches_through_are_shifted_off_an_authors() {
        assert_eq!(kotlin_local_spelling("UByte"), "UByte_");
        assert_eq!(kotlin_local_spelling("ForgeDomainTag"), "ForgeDomainTag_");
        assert_eq!(kotlin_local_spelling("MY_CONST"), "MY_CONST_");
        assert_eq!(kotlin_local_spelling("Foo_"), "Foo__");
        assert_eq!(kotlin_local_spelling("com"), "com_");
        assert_eq!(kotlin_local_spelling("kotlin"), "kotlin_");
        assert_eq!(kotlin_local_spelling("sceEvents"), "sceEvents_");
        assert_eq!(kotlin_local_spelling("sce_x"), "sce_x_");
        assert_eq!(kotlin_local_spelling("engineRpm"), "engineRpm");
        assert_eq!(kotlin_local_spelling("rpm"), "rpm");
        assert_eq!(kotlin_local_spelling("events"), "events");
        assert_eq!(kotlin_local_spelling("scene"), "scene");
        assert_eq!(kotlin_local_spelling("comma"), "comma");
        assert_eq!(kotlin_local_spelling("x_"), "x_");
        // Injective: no two names the document keeps apart meet.
        let names = [
            "Foo", "Foo_", "Foo__", "com", "com_", "x", "x_", "sce_a", "sce_a_",
        ];
        let spelled: std::collections::BTreeSet<String> =
            names.iter().map(|n| kotlin_local_spelling(n)).collect();
        assert_eq!(spelled.len(), names.len(), "{spelled:?}");
    }

    /// The standard type names the generator keeps a declared type off are the
    /// ones its type mapping writes, and nothing else is shifted.
    #[test]
    fn kotlin_type_names_are_the_ones_the_mapping_writes() {
        let written: std::collections::BTreeSet<&str> = [
            SceType::Uint8,
            SceType::Uint16,
            SceType::Uint32,
            SceType::Uint64,
            SceType::Int8,
            SceType::Int16,
            SceType::Int32,
            SceType::Int64,
            SceType::Float32,
            SceType::Float64,
            SceType::Bool,
            SceType::String,
            SceType::Bytes,
        ]
        .iter()
        .map(kotlin_type)
        .collect();
        let kept: std::collections::BTreeSet<&str> = KOTLIN_TYPE_NAMES.iter().copied().collect();
        assert_eq!(written, kept);
        assert_eq!(kotlin_declared_type_name("UByte"), "UByte_");
        assert_eq!(kotlin_declared_type_name("UByte_"), "UByte__");
        assert_eq!(kotlin_declared_type_name("Status"), "Status");
        assert_eq!(kotlin_declared_type_name("Integer"), "Integer");
    }

